    {
      "card_ids": ["C01"],
      "claim": "Compound 33, which shares an isopropylamino-substituted heteroaromatic core with the query, achieved a brain-to-plasma Kp of 11.4 in mice with negligible P-gp efflux, directly demonstrating good CNS penetration for a structurally relevant analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In vivo oral dosing in mice showed that biarylamide analogues with similar amide/heteroaromatic architecture traverse the BBB and reach excellent brain drug levels, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "L655,708, a moderately lipophilic heteroaromatic compound, exhibited a rat brain uptake index of 59%, indicating reasonable first-pass brain extraction and supporting CNS penetration for the query's chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "MOMIPP, a methoxy-substituted heteroaromatic compound, readily crossed the BBB with brain concentrations 50-60% of plasma for up to 8 h, showing sustained meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental records uniformly demonstrate BBB permeability or meaningful brain exposure for structurally related compounds, including direct Kp values, brain/plasma ratios, and brain uptake indices; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct in vivo brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter status for the query was not directly measured.",
    "No human CNS exposure data for the query or close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

